<script setup>
import { ref } from 'vue';
import { useRouter } from 'vue-router';
import MobileAppNavbar from '@/mobile/components/layout/mobile-app-navbar.vue';
import MobileInputAiChat from '@/mobile/components/business/mobile-input-ai-chat.vue';
import MobileSettingsSheet from '@/mobile/components/dialog/mobile-settings-sheet.vue';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
