import { useAIChatStore } from '@/store/modules/AIChat';
import { routerToAlienChat } from '@/router/navigation';

const router = useRouter();

// 变量区域
const aiChatStore = useAIChatStore();
const logo = ref(import.meta.env.VITE_APP_LOGO);
const settingsSheetVisible = ref(false);
const refInput = ref(null);

// 显示的工具列表，只显示前三个
const displayTools = [
    { name: 'aiChatCompanion', icon: '/static/images/ai_chat_companion.png', path: ROUTER_PATHS.CREATE_CHARACTER, type: 'route' },
    { name: 'textTool', icon: '/static/images/text_tool.png', path: ROUTER_PATHS.TEXT_TOOL, type: 'route' },
    { name: 'imageAnalysis', icon: '/static/images/image_analysis.png', path: ROUTER_PATHS.IMAGE_TOOL, type: 'route' },
    { name: 'textToImage', icon: '/static/images/text-to-image-icon.png', path: ROUTER_PATHS.TEXT_TO_IMAGE, type: 'route', openInNewTab: true },
].filter(tool => !tool.isDev || import.meta.env.DEV);

// 点击事件区域
const handleToolClick = (tool) => {
  if (tool.type === 'route' && tool.path) {
    router.push(tool.path);
  }
};

// 自定义事件区域
const handleSettingsOpened = () => {
  console.log('Settings sheet opened');
};

const handleSettingsClosed = () => {
  console.log('Settings sheet closed');
};

const handleSettingsClose = () => {
  console.log('Settings sheet close event');
};

const onClickSend = (data) => {
    refInput.value.isLoading = false;
    // 存储AI提问参数
    aiChatStore.setAIChatParams(data);
    // 跳转到外星人聊天页面
    routerToAlienChat();
}
</script>
